#include <stdio.h>

int count_pairs(int L) {
    int res = 1;
    int temp = L;
    for (int p = 2; p * p <= temp; p++) {
        if (temp % p == 0) {
            int e = 0;
            while (temp % p == 0) {
                temp /= p;
                e++;
            }
            res *= (2 * e + 1);
        }
    }
    if (temp > 1) {
        res *= 3; // (2*1 + 1)
    }
    return (res + 1) / 2;
}

