using namespace std;

int countPairs(int L) {
    int res = 0;
    for (int g = 1; g * g <= L; g++) {
        if (L % g == 0) {
            int d1 = g;
            int d2 = L / g;

            // For divisor g
            int m = L / d1;
            for (int x = 1; x * x <= m; x++) {
                if (m % x == 0) {
                    int y = m / x;
                    if (__gcd(x, y) == 1) {
                        if (x <= y) res++;
                    }
                }
            }

            // For the paired divisor if different
            if (d1 != d2) {
                m = L / d2;
                for (int x = 1; x * x <= m; x++) {
                    if (m % x == 0) {
                        int y = m / x;
                        if (__gcd(x, y) == 1) {
                            if (x <= y) res++;
                        }
                    }
                }
            }
        }
    }
    return res;
}

