using namespace std;

int main() {
    long long L;
    while (cin >> L && L != 0) {
        // Find all divisors of L
        vector<long long> divs;
        for (long long i = 1; i * i <= L; i++) {
            if (L % i == 0) {
                divs.push_back(i);
                if (i != L / i) divs.push_back(L / i);
            }
        }

        int count = 0;
        int n = divs.size();
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                long long a = divs[i], b = divs[j];
                // lcm(a,b) = a*b/gcd(a,b)
                long long g = __gcd(a, b);
                long long lcm_ab = a / g * b;
                if (lcm_ab == L) {
                    count++;
                }
            }
        }

        cout << count << "\n";
    }
    return 0;
}

