    cin.tie(nullptr);

    long long L;
    while (cin >> L && L) {
        long long n = L;
        int distinctPrimes = 0;

        for (long long p = 2; p * p <= n; ++p) {
            if (n % p == 0) {
                ++distinctPrimes;
                while (n % p == 0) n /= p;
            }
        }
        if (n > 1) ++distinctPrimes;

        // Number of ordered pairs (a,b) with lcm(a,b)=L is 3^k,
        // where k is the number of distinct prime factors of L.
        // Since we need a <= b, answer is (3^k + 1) / 2.
        long long ans = 1;
        for (int i = 0; i < distinctPrimes; ++i) ans *= 3;
        ans = (ans + 1) / 2;

        cout << L << " " << ans << '\n';
    }

    return 0;
}

