    }

    static long countPairs(int L) {
        long result = 1;
        int temp = L;
        for (int p = 2; p * p <= temp; p++) {
            if (temp % p == 0) {
                int k = 0;
                while (temp % p == 0) {
                    temp /= p;
                    k++;
                }
                result *= (2L * k + 1);
            }
        }
        if (temp > 1) {
            // remaining prime factor with exponent 1
            result *= (2L * 1 + 1);
        }
        return result;
    }
