import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedInputStream in = new BufferedInputStream(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            long L = nextLong(in);
            if (L == Long.MIN_VALUE) break; // EOF
            if (L == 0) break;

            long n = L;
            int distinctPrimeCount = 0;

            for (long p = 2; p * p <= n; p += (p == 2 ? 1 : 2)) {
                if (n % p == 0) {
                    distinctPrimeCount++;
                    while (n % p == 0) n /= p;
                }
            }
            if (n > 1) distinctPrimeCount++;

            long ans = 1L << distinctPrimeCount;
            ans = (ans + 1) / 2;

            out.append(L).append(' ').append(ans).append('\n');
        }

        System.out.print(out.toString());
    }

    private static long nextLong(InputStream in) throws IOException {
        int c;
        do {
            c = in.read();
            if (c == -1) return Long.MIN_VALUE;
        } while (c <= ' ');

        long sign = 1;
        if (c == '-') {
            sign = -1;
            c = in.read();
        }

        long val = 0;
        while (c > ' ') {
            val = val * 10 + (c - '0');
            c = in.read();
        }
        return val * sign;
    }
}

