import sys

def count_pairs_lcm(L: int) -> int:
    n = L
    distinct_primes = 0
    p = 2
    while p * p <= n:
        if n % p == 0:
            distinct_primes += 1
            while n % p == 0:
                n //= p
        p += 1 if p == 2 else 2  # after 2, test only odd numbers
    if n > 1:
        distinct_primes += 1

    # Number of ordered coprime factor-splits per prime is 3:
    # exponent goes entirely to a, entirely to b, or to both.
    # So ordered pairs = 3^k, where k is number of distinct prime factors.
    # Among them, only (L, L) is symmetric; all others come in swapped pairs.
    # Hence unordered pairs with a <= b = (3^k + 1) // 2.
    return (pow(3, distinct_primes) + 1) // 2

